create table if not exists private.buklod_r38_referral_state(
referral_id uuid primary key references public.buklod_referrals(id) on delete cascade,referrer_user_id uuid not null references auth.users(id) on delete cascade,referred_user_id uuid not null references auth.users(id) on delete cascade,canonical_state text not null default 'JOINED' check(canonical_state in('INVITED','JOINED','QUALIFYING','ACTIVE_REFERRAL','RETAINED','EARNING_WINDOW_ENDED','DISQUALIFIED','BLOCKED_FRAUD')),joined_at timestamptz not null default now(),account_verified boolean not null default false,meaningful_active_days integer not null default 0 check(meaningful_active_days>=0),qualifying_activity_count integer not null default 0 check(qualifying_activity_count>=0),qualified_at timestamptz,earning_window_start timestamptz,earning_window_end timestamptz,retained_at timestamptz,disqualified_at timestamptz,disqualified_reason text,fraud_blocked_at timestamptz,last_evaluated_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(referred_user_id),check(referrer_user_id<>referred_user_id));
create index if not exists buklod_r38_referral_state_referrer_idx on private.buklod_r38_referral_state(referrer_user_id,canonical_state);
create index if not exists buklod_r38_referral_state_window_idx on private.buklod_r38_referral_state(earning_window_end) where canonical_state in('ACTIVE_REFERRAL','RETAINED');

create table if not exists private.buklod_r38_rcu_ledger(id uuid primary key default gen_random_uuid(),referrer_user_id uuid not null references auth.users(id) on delete cascade,referred_user_id uuid not null references auth.users(id) on delete cascade,referral_id uuid not null references public.buklod_referrals(id) on delete cascade,source_bcu_ledger_id uuid references private.buklod_r36_bcu_ledger(id) on delete restrict,direction text not null default 'credit' check(direction in('credit','debit')),units numeric(20,6) not null check(units>=0),qualification_state text not null default 'qualified' check(qualification_state in('qualified','held','reversed')),event_key text not null,occurred_at timestamptz not null default now(),policy_version text not null default 'r38_unified_economy_v1',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(referrer_user_id,event_key));
create index if not exists buklod_r38_rcu_ledger_referrer_time_idx on private.buklod_r38_rcu_ledger(referrer_user_id,occurred_at);
create index if not exists buklod_r38_rcu_ledger_referred_time_idx on private.buklod_r38_rcu_ledger(referred_user_id,occurred_at);

create table if not exists private.buklod_r38_economic_periods(id uuid primary key default gen_random_uuid(),period_key text not null unique,period_start timestamptz not null,period_end timestamptz not null,status text not null default 'OPEN' check(status in('OPEN','ESTIMATING','RECONCILING','READY_FOR_FINALIZATION','FINALIZED','PAYOUT_READY','CLOSED')),estimated_revenue numeric(20,4) not null default 0,estimated_costs numeric(20,4) not null default 0,estimated_distributable_base numeric(20,4) not null default 0,estimated_referral_pool numeric(20,4) not null default 0,finalized_revenue numeric(20,4),finalized_costs numeric(20,4),finalized_distributable_base numeric(20,4),finalized_bayanihan_pool numeric(20,4),finalized_referral_pool numeric(20,4),finalized_founder_allocation numeric(20,4),finalized_growth_allocation numeric(20,4),finalized_reserve_allocation numeric(20,4),finalized_total_qualified_bcu numeric(20,6),finalized_total_qualified_rcu numeric(20,6),finalization_id uuid,policy_version text not null default 'r38_unified_economy_v1',policy_snapshot jsonb,finalized_by uuid references auth.users(id) on delete set null,finalized_at timestamptz,closed_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(period_end>period_start));
create table if not exists private.buklod_r38_financial_entries(id uuid primary key default gen_random_uuid(),period_id uuid not null references private.buklod_r38_economic_periods(id) on delete restrict,entry_kind text not null check(entry_kind in('REVENUE','INFRASTRUCTURE','DATABASE','STORAGE','BANDWIDTH','MEDIA','AI_TTS','PAYMENT_PROCESSING','PLATFORM_FEE','INVALID_TRAFFIC','REFUND_CHARGEBACK','OPERATIONAL_COST','TAX_STATUTORY','OTHER_COST','ADJUSTMENT')),direction text not null check(direction in('revenue','cost')),amount numeric(20,4) not null check(amount>=0),source_system text not null default 'manual_admin',external_reference text,idempotency_key text not null unique,recognized_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists buklod_r38_financial_entries_period_idx on private.buklod_r38_financial_entries(period_id,recognized_at);

create table if not exists private.buklod_r38_referral_earnings_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,period_id uuid references private.buklod_r38_economic_periods(id) on delete restrict,bucket text not null check(bucket in('AVAILABLE','RESERVED','PAID')),direction text not null check(direction in('credit','debit')),amount numeric(20,4) not null check(amount>=0),entry_type text not null check(entry_type in('PERIOD_FINALIZATION','WITHDRAWAL_RESERVE','WITHDRAWAL_RELEASE','PAYOUT_PAID','ADMIN_ADJUSTMENT','REVERSAL')),event_key text not null,withdrawal_request_id uuid,description text,created_by uuid references auth.users(id) on delete set null,policy_version text not null default 'r38_unified_economy_v1',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(user_id,event_key));
create index if not exists buklod_r38_referral_earnings_user_idx on private.buklod_r38_referral_earnings_ledger(user_id,created_at);
create table if not exists private.buklod_r38_referral_withdrawals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,requested_amount numeric(20,4) not null check(requested_amount>0),currency text not null default 'PHP',status text not null default 'REQUESTED' check(status in('REQUESTED','UNDER_REVIEW','APPROVED','PROCESSING','PAID','REJECTED','CANCELLED','FAILED')),payout_method text,payout_profile_ref text,payout_destination_masked text,request_idempotency_key text not null,requested_at timestamptz not null default now(),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,approved_by uuid references auth.users(id) on delete set null,approved_at timestamptz,processing_at timestamptz,paid_at timestamptz,payout_transaction_ref text,rejection_reason text,failure_reason text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,request_idempotency_key));
alter table private.buklod_r38_referral_earnings_ledger drop constraint if exists buklod_r38_referral_earnings_withdrawal_fk;
alter table private.buklod_r38_referral_earnings_ledger add constraint buklod_r38_referral_earnings_withdrawal_fk foreign key(withdrawal_request_id) references private.buklod_r38_referral_withdrawals(id) on delete restrict;
create index if not exists buklod_r38_withdrawal_status_idx on private.buklod_r38_referral_withdrawals(status,requested_at);
create index if not exists buklod_r38_withdrawal_user_idx on private.buklod_r38_referral_withdrawals(user_id,requested_at);

create table if not exists private.buklod_r38_fraud_flags(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,referral_id uuid references public.buklod_referrals(id) on delete cascade,flag_type text not null,severity text not null default 'LOW' check(severity in('LOW','MEDIUM','HIGH','CRITICAL')),status text not null default 'OPEN' check(status in('OPEN','REVIEWING','CLEARED','CONFIRMED')),blocks_economics boolean not null default false,evidence jsonb not null default '{}'::jsonb,detected_at timestamptz not null default now(),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,resolution_notes text,created_at timestamptz not null default now());
create index if not exists buklod_r38_fraud_user_open_idx on private.buklod_r38_fraud_flags(user_id,status) where status in('OPEN','REVIEWING','CONFIRMED');
create table if not exists private.buklod_r38_economy_audit_log(id bigint generated by default as identity primary key,actor_user_id uuid references auth.users(id) on delete set null,action text not null,target_type text not null,target_id text,before_state jsonb,change_state jsonb,after_state jsonb,reason text,event_key text unique,created_at timestamptz not null default now());

alter table private.buklod_special_collectible_definitions_v2 add column if not exists reward_scope text check(reward_scope in('GENERAL','SHOW_FAITH','ORG'));
alter table private.buklod_special_collectible_definitions_v2 add column if not exists scope_review_required boolean not null default true;

create or replace function private.buklod_r38_policy_config_v1() returns jsonb language sql stable security definer set search_path='' as $$select coalesce((select p.config from private.buklod_r36_economy_policy_versions p where p.policy_version='r38_unified_economy_v1' limit 1),'{}'::jsonb);$$;
create or replace function private.buklod_r38_flag_enabled_v1(p_flag text) returns boolean language sql stable security definer set search_path='' as $$select coalesce((private.buklod_r38_policy_config_v1()->'activation'->>p_flag)::boolean,false);$$;
create or replace function private.buklod_r38_referral_window_months_v1() returns integer language sql stable security definer set search_path='' as $$select greatest(coalesce((private.buklod_r38_policy_config_v1()->'referral'->>'earning_window_months')::integer,6),1);$$;